def readg(s): return [list(map(int,re.findall(r'\d+',line))) for line in s.strip().splitlines() if line.strip()]
def shape(pts,sym=True):
 forms=[]
 for k in range(8 if sym else 1):
  p=[]
  for r,c0 in pts:
   c1=-c0 if k>=4 else c0; t=k%4
   if t==0:x,y=r,c1
   elif t==1:x,y=c1,-r
   elif t==2:x,y=-r,-c1
   else:x,y=-c1,r
   p.append((x,y))
  mr=min(x for x,y in p); mc=min(y for x,y in p)
  forms.append(tuple(sorted((x-mr,y-mc) for x,y in p)))
 return min(forms)
def comps(g):
 H,W=len(g),len(g[0]); seen=set();out=[]
 for r in range(H):
  for c0 in range(W):
   v=g[r][c0]
   if v==g[0][0] or (r,c0) in seen: continue
   st=[(r,c0)];seen.add((r,c0));pts=[]
   while st:
    a,b=st.pop();pts.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=a+da,b+db
     if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==v: seen.add((x,y));st.append((x,y))
   out.append((v,pts))
 return out
for txt in texts:
 for k in range(1,6):
  m=re.search(rf'Demo pair {k} input \(\d+x\d+\):\n(.*?)\nDemo pair {k} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance|\Z)',txt,re.S)
  if m:
   a,b=readg(m.group(1)),readg(m.group(2)); changed={(r,c0) for r in range(len(a)) for c0 in range(len(a[0])) if a[r][c0]!=b[r][c0]}
   target=next((v,p) for v,p in comps(a) if any(q in changed for q in p)); outcolor=b[next(iter(changed))[0]][next(iter(changed))[1]]; key=shape(target[1]); print('\nD',k,'target',target[0],'->',outcolor,'size',len(target[1]),'shape',key)
