import sqlite3,re
p='/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-hermesagentlearner-1792485342/attempts/da427609defb4f66ade808b60012359c/system/state/hermes/state.db'
c=sqlite3.connect('file:'+p+'?mode=ro',uri=True)
msgs=dict(c.execute("select id,content from messages where session_id='60a8cbfd-f014-4c64-8333-671d319b9353' and role='user' and id in (1064,1088,1091,1093,1251,1386)"))
def getgrid(text, label):
    m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n(.*?)(?=\n(?:Demo pair|Same instance|Wrong attempts|Reply with|$))',text,re.S)
    if not m: raise ValueError('missing '+label)
    h,w=map(int,m.group(1,2)); rows=[[int(x) for x in line.split()] for line in m.group(3).strip().splitlines()]
    if len(rows)!=h or any(len(r)!=w for r in rows): print('BAD',label,h,w,len(rows),[len(r) for r in rows])
    return rows
def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c0 in range(w):
   if g[r][c0] in (next(iter([]),-999),): pass
   if (r,c0) in seen: continue
   col=g[r][c0]; q=[(r,c0)];seen.add((r,c0)); pts=[]
   while q:
    x,y=q.pop();pts.append((x,y))
    for z in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     a,b=z
     if 0<=a<h and 0<=b<w and z not in seen and g[a][b]==col:seen.add(z);q.append(z)
   if col != 9: out.append((col,pts))
 return out
def shape(pts):
 r0=min(r for r,c0 in pts); c0=min(c for r,c0 in pts)
 return '/'.join(''.join('#' if (r0+i,c0+j) in pts else '.' for j in range(max(c0x for _,c0x in pts)-c0+1)) for i in range(max(rx for rx,_ in pts)-r0+1))
for d,id in enumerate([1088,1091,1093,1251,1386],1):
 txt=msgs[id]
 a=getgrid(txt,f'Demo pair {d} input'); b=getgrid(txt,f'Demo pair {d} output')
 dif=[(r,c0,a[r][c0],b[r][c0]) for r in range(len(a)) for c0 in range(len(a[0])) if a[r][c0]!=b[r][c0]]
 print('\nDEMO',d,'DIFF',len(dif),dif)
 print('DIFF groups by origcolor', {x:sum(1 for _,_,x2,_ in dif if x2==x) for x in sorted(set(z[2] for z in dif))})
 co=comps(a); by={cl:[ps for cl2,ps in co if cl2==cl] for cl in set(cl for cl,_ in co)}
 print('changed components:', [(old,col, len(ps),shape(set(ps))) for old,newcol in set((x[2],x[3]) for x in dif) for c,ps in co if c==old and any(pos in set(ps) for r,c0,_,_ in dif for pos in [(r,c0)])])
 print('all objects:',[(cl,len(ps),shape(set(ps))) for cl,ps in co if len(ps)>1])
# test components
text=msgs[1064]; test=getgrid(text,'Test input'); print('\nTEST components:',[(cl,len(ps),shape(set(ps)), (min(r for r,c0 in ps),min(c0 for r,c0 in ps))) for cl,ps in comps(test) if cl!=7])

