   out.append((v,cells))
 return out
def grid_between(s,start,end):
 a=s.index(start)+len(start); b=s.index(end,a); rows=[]
 for line in s[a:b].strip().splitlines():
  if re.fullmatch(r'[0-9 ]+',line.strip()): rows.append([int(x) for x in line.split()])
