 for v,cells in comps(gi,bg):
  changed=[(r,c) for r,c in cells if gi[r][c]!=go[r][c]]
  if changed:
   print('CHANGED',v,'->',sorted(set(go[r][c] for r,c in changed)),'cells',sorted(changed))
 print('OBJECTS')
 for v,cells in comps(gi,bg):
  if len(cells)>1: print(v,len(cells),sorted(cells))
s=msgs[min(msgs)]; m=re.search(r'Test input \\((\\d+)x(\\d+)\\):',s); h,w=map(int,m.groups()); g=grid_between(s,m.group(0),'Wrong attempts used:'); bg=collections.Counter(sum(g,[])).most_common(1)[0][0]
print('TEST',h,w,'bg',bg)
for v,cells in comps(g,bg): print(v,len(cells),sorted(cells))
PY"""
