def getgrid(text,label):
 m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n(.*?)(?=\n(?:Demo pair|Same instance|Wrong attempts|Reply with|$))',text,re.S)
 if not m: raise ValueError('missing '+label)
 h,w=map(int,m.group(1,2)); rows=[[int(x) for x in line.split()] for line in m.group(3).strip().splitlines()]
 if len(rows)!=h or any(len(r)!=w for r in rows): print('BAD',label,h,w,len(rows),[len(r) for r in rows])
 return rows
def comps(g,bg):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen or g[r][c]==bg:continue
   col=g[r][c]; q=[(r,c)];seen.add((r,c));pts=[]
   while q:
    x,y=q.pop();pts.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==col:seen.add((a,b));q.append((a,b))
   out.append((col,pts))
 return out
def shape(pts):
 rs=[r for r,c in pts];cs=[c for r,c in pts];r0=min(rs);c0=min(cs)
 return '/'.join(''.join('#' if (r0+i,c0+j) in pts else '.' for j in range(max(cs)-c0+1)) for i in range(max(rs)-r0+1))
for d,id in enumerate([1088,1091,1093,1251,1386],1):
 txt=msgs[id]; a=getgrid(txt,f'Demo pair {d} input');b=getgrid(txt,f'Demo pair {d} output'); bg=max(set(x for row in a for x in row),key=lambda x:sum(row.count(x) for row in a))
 dif=[(r,c,a[r][c],b[r][c]) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]!=b[r][c]]
 co=comps(a,bg)
 ch=[]
 for col,pts in co:
  changes=[(r,c,a[r][c],b[r][c]) for r,c in pts if a[r][c]!=b[r][c]]
  if changes: ch.append((col,len(pts),shape(set(pts)),changes))
 print('\nDEMO',d,'bg',bg,'DIFF',len(dif),dif,'CHANGED COMPONENTS',ch)
 print('OBJECTS:',[(cl,len(ps),shape(set(ps))) for cl,ps in co if len(ps)>1])
text=msgs[1064];test=getgrid(text,'Test input');bg=7
print('\nTEST components:',[(cl,len(ps),shape(set(ps)),(min(r for r,c in ps),min(c for r,c in ps))) for cl,ps in comps(test,bg)])

