def comps(g):
 H=len(g); W=len(g[0]); seen=set(); out=[]
 for r in range(H):
  for col in range(W):
   v=g[r][col]
   if v==next(iter(collections.Counter(sum(g,[])).most_common(1)))[0] or (r,col) in seen: continue
   todo=[(r,col)]; seen.add((r,col)); cells=[]
   while todo:
    x,y=todo.pop(); cells.append((x,y))
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and g[nx][ny]==v:
      seen.add((nx,ny)); todo.append((nx,ny))
   rs=[x for x,y in cells]; cs=[y for x,y in cells]
   out.append((v,len(cells),(min(rs),max(rs),min(cs),max(cs)),cells))
 return sorted(out,key=lambda x:(-x[1],x[0],x[2]))
