 if not mt: continue
 ix,H,W,inp,out=mt.groups(); parse=lambda s:[[int(x) for x in l.split()] for l in s.splitlines() if l.strip()]
 a,b=parse(inp),parse(out); bg=collections.Counter(sum(a,[])).most_common(1)[0][0]
 diffs={(r,col) for r in range(len(a)) for col in range(len(a[0])) if a[r][col]!=b[r][col]}
 print(f'\nDEMO {ix} bg{bg} changed={len(diffs)}')
 for color,n,bbox,cells in comps(a):
  ch=[pt for pt in cells if pt in diffs]
  if ch or n>=2:
   # crop shape, mark changed cells * and same-source cells #
   r0,r1,c0,c1=bbox
   shape=' / '.join(''.join('*' if (r,c) in diffs else '#' if a[r][c]==color else '.' for c in range(c0,c1+1)) for r in range(r0,r1+1))
