import sqlite3, os, re, collections
c=sqlite3.connect(os.path.join(os.environ['HERMES_HOME'],'state.db')); sid='60a8cbfd-f014-4c64-8333-671d319b9353'
rows=c.execute("select id,content from messages where session_id=? and role='user' order by id",(sid,)).fetchall()
def comps(g, bg):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for x in range(w):
   v=g[r][x]
   if v==bg or (r,x) in seen: continue
   q=[(r,x)]; seen.add((r,x)); co=[]
   while q:
    a,b=q.pop(); co.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     y,z=a+da,b+db
     if 0<=y<h and 0<=z<w and (y,z) not in seen and g[y][z]==v: seen.add((y,z)); q.append((y,z))
   out.append((v,co))
 return out
for mid,text in rows:
 for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)(?=\nDemo pair \d+ output \(|\nSame instance\.)',text,re.S):
  k,h,w,body=m.group(1),int(m.group(2)),int(m.group(3)),m.group(4); sub=text[m.start():]
  om=re.search(r'Demo pair '+k+r' output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance\.)',sub,re.S)
  if not om: continue
  a=[list(map(int,x.split())) for x in body.splitlines() if re.fullmatch(r'[0-9 ]+',x)]
  b=[list(map(int,x.split())) for x in om.group(1).splitlines() if re.fullmatch(r'[0-9 ]+',x)]
  ds=[(r,x,a[r][x],b[r][x]) for r in range(len(a)) for x in range(len(a[0])) if a[r][x]!=b[r][x]]
  bg=collections.Counter(sum(a,[])).most_common(1)[0][0]
  print('\nPAIR',k,'bg',bg,'diffs',ds)
  print('components:')
  for color,co in sorted(comps(a,bg),key=lambda z:(z[0],min(z[1]))):
   if len(co)>1 or color in (x[2] for x in ds): print(color,len(co),sorted(co))

